void draw_racket_and_effects(void)
{
    if (INPUT_FLAGS->spell_flags & SPELL_OVERLAY_ACTIVE) {
        image_buffer_cursor->sprite_or_frame = (int)(game_art_base + 0x7536);
        image_buffer_cursor->x = (short)racket_object->previous_x_snapshot;
        image_buffer_cursor->y = (short)racket_object->y;
        image_buffer_cursor->flags = 0;
        ++image_buffer_cursor;
    }
    if (INPUT_FLAGS->control_flags & CONTROL_RELEASE_ANIMATION) {
        temp = racket_object->animation_step_4c;
        if (temp < 0xc) {
            temp = 0xc - temp;
            goto select_racket_frame; /* Rejoin the shared frame selector. */
        }
        sprite_frame_offset_scratch = racket_effect_frames_c[temp].image_offset;
    } else if (INPUT_FLAGS->control_flags & CONTROL_MOVE_ANIMATION) {
        temp = racket_object->animation_step_54;
        if (temp >= 8) {
            temp -= 8;
            goto select_racket_frame; /* Rejoin the shared frame selector. */
        }
        sprite_frame_offset_scratch = racket_movement_animation_frames[temp].image_offset;
    } else {
        temp = racket_object->sprite_frame_index;
select_racket_frame:;
        if (INPUT_FLAGS->control_flags & CONTROL_ALTERNATE_FRAME) {
            sprite_frame_offset_scratch = racket_effect_frames_a[temp].image_offset;
        } else {
            sprite_frame_offset_scratch = racket_sprite_frames[temp].image_offset;
        }
    }
    if (!(INPUT_FLAGS->control_flags & CONTROL_BODY_HIDDEN)) {
        image_buffer_cursor->sprite_or_frame = (int)(sprite_frame_offset_scratch + game_art_base);
        image_buffer_cursor->x = (short)racket_object->x;
        image_buffer_cursor->y = (short)racket_object->y;
        image_buffer_cursor->flags = 0;
        ++image_buffer_cursor;
        racket_object->sprite_pointer = (image_buffer_cursor - 1)->sprite_or_frame;
        if (INPUT_FLAGS->control_flags & CONTROL_GUARD_ANIMATION) {
            result = racket_guard_animation_frames[temp].image_offset;
            image_buffer_cursor->sprite_or_frame = (int)(result + game_art_base);
            image_buffer_cursor->x = (short)racket_object->x;
            image_buffer_cursor->y = (short)racket_object->y;
            image_buffer_cursor->flags = 0;
            ++image_buffer_cursor;
        }
        if (INPUT_FLAGS->spell_flags & SPELL_SHIELD_ACTIVE) {
            result = racket_shield_flash_frames[((frames >> 2) & 1)].image_offset;
            image_buffer_cursor->sprite_or_frame = (int)(spell_art_base + result);
            image_buffer_cursor->x = (short)racket_object->x;
            image_buffer_cursor->y = (short)racket_object->y;
            image_buffer_cursor->flags = 0;
            ++image_buffer_cursor;
        }
        if ((racket_object->capture_timer > 0 || INPUT_FLAGS->control_flags & CONTROL_TIMED_EFFECT) && !(INPUT_FLAGS->control_flags & CONTROL_RELEASE_ANIMATION)) {
            if (--racket_object->effect_timer_40 <= 0) {
                work_value = racket_spell_animation_frames[++racket_object->effect_frame_44].duration_or_delta;
                if (work_value < 0) {
                    racket_object->effect_frame_44 += work_value;
                    work_value = racket_spell_animation_frames[racket_object->effect_frame_44].duration_or_delta;
                }
                racket_object->effect_timer_40 = work_value;
            }
            if (racket_object->capture_timer == 1) {
                result = racket_spell_animation_frames[racket_object->effect_frame_44].image_offset;
            } else {
                result = spell_impact_animation_frames[racket_object->effect_frame_44].image_offset;
            }
            image_buffer_cursor->sprite_or_frame = (int)(result + spell_art_base);
            image_buffer_cursor->x = (unsigned short)((racket_object->x - (racket_object->sprite_height >> 1)) + 4);
            image_buffer_cursor->y = (short)racket_object->y;
            image_buffer_cursor->flags = 0;
            ++image_buffer_cursor;
        }
    }
    if (INPUT_FLAGS->spell_flags & SPELL_EFFECT_ACTIVE) {
        result = racket_effect_frames_b[temp].image_offset;
        image_buffer_cursor->sprite_or_frame = (int)(result + game_art_base);
        image_buffer_cursor->x = (short)racket_object->x;
        image_buffer_cursor->y = (short)racket_object->y;
        image_buffer_cursor->flags = 0;
        ++image_buffer_cursor;
    }
}

void start_racket_release_animation(void) {
    if (!(INPUT_FLAGS->control_flags & CONTROL_RELEASE_ANIMATION)) {
        submit_audio_request(0xb);
        INPUT_FLAGS->control_flags |= 1;
        racket_object->animation_timer_48 = 4;
        racket_object->animation_step_4c = 0xd - racket_object->sprite_frame_index;
    }
}

void start_racket_movement_animation(void) {
    submit_audio_request(0x26);
    INPUT_FLAGS->control_flags |= 2;
    racket_object->animation_timer_50 = 4;
    racket_object->animation_step_54 = 0;
}

void update_racket_dimensions(void) {
    racket_object->sprite_height = get_racket_sprite_height() - 2;
    temp = racket_object->sprite_height >> 1;
    racket_object->min_x = temp + 0x10;
    racket_object->max_x = 0x130 - temp;
    set_mouse_horizontal_bounds(racket_object->min_x, racket_object->max_x);
    temp = racket_object->x;
    if (INPUT_FLAGS->control_flags & CONTROL_REVERSE_CONTROLS)
        temp = racket_object->max_x + racket_object->min_x - temp;
    move_mouse_to(temp, mouse_y_mean_recent);
}

void update_racket_movement_bounds(void) {
    if (INPUT_FLAGS->spell_flags & SPELL_SHIELD_ACTIVE) temp = 0x18;
    else temp = 0xbc;
    racket_object->min_y = temp;
    racket_object->max_y = 0xbc;
    set_mouse_vertical_bounds(racket_object->min_y, racket_object->max_y);
    move_mouse_to(mouse_x_average_recent, racket_object->y);
}

int get_racket_sprite_height(void) {
    unsigned char *address;
    address = game_art_base + racket_sprite_frames[racket_object->sprite_frame_index].image_offset;
    return ((struct BobFrameMetrics *)address)->width;
}
